                          const stops = q.layout?.numberOfStops || 0;
                          const entrances = q.layout?.numberOfEntrances || stops;
                          const typeChar = q.layout?.entrances === 'AB' ? 'P' : (q.layout?.entrances === 'AC' ? 'U' : 'N');
