                  cat.items.push({ id: generateId(), description: 'Balné a manipulácia', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); 
              } 
          }
          return newData;
      });
