                        onAddItem={handleAddItem}
                        onUpdateItem={(cid, iid, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)}))}
