export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!sessionStorage.getItem('auth'));
  const [activeModule, setActiveModule] = useState<'launcher' | 'lift' | 'rs'>('launcher');

  const handleLogin = () => {
    sessionStorage.setItem('auth', 'true');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    sessionStorage.removeItem('auth');
    setIsAuthenticated(false);
    setActiveModule('launcher');
  };

  if (!isAuthenticated) {
    return <LoginGate onLogin={handleLogin} />;
  }

  if (activeModule === 'lift') {
    return <LiftModule onBack={() => setActiveModule('launcher')} onLogout={handleLogout} />;
  }

  if (activeModule === 'rs') {
    return <RsModule onBack={() => setActiveModule('launcher')} onLogout={handleLogout} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6 md:p-12 font-sans">
      <div className="max-w-5xl w-full">
        <header className="text-center mb-12 animate-in fade-in slide-in-from-top-4 duration-700">
          <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-3">SmartQuote SK</h1>
          <p className="text-lg text-gray-500">Vyberte si modul pre nacenenie projektu</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* LIFT MODULE BUTTON */}
          <button 
            onClick={() => setActiveModule('lift')}
            className="group relative bg-white p-1 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border-2 border-transparent hover:border-blue-500 overflow-hidden"
          >
            <div className="p-8 h-full flex flex-col text-left">
              <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-500">
                <LayoutTemplate size={32} />
              </div>
              <h2 className="text-2xl font-bold text-gray-900 mb-2">Kompletný Výťah</h2>
              <p className="text-gray-500 mb-8 flex-grow">Nacenenie novej inštalácie alebo kompletnej rekonštrukcie výťahu vrátane šachty a komponentov.</p>
              <div className="flex items-center gap-2 text-blue-600 font-bold">
                Spustiť modul <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
              </div>
            </div>
          </button>

          {/* RS MODULE BUTTON */}
          <button 
            onClick={() => setActiveModule('rs')}
            className="group relative bg-white p-1 rounded-2xl shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border-2 border-transparent hover:border-emerald-500 overflow-hidden"
          >
            <div className="p-8 h-full flex flex-col text-left">
              <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-500">
                <Cpu size={32} />
              </div>
              <h2 className="text-2xl font-bold text-gray-900 mb-2">Riadiace Systémy (RS)</h2>
              <p className="text-gray-500 mb-8 flex-grow">Modernizácia a výmena riadenia. Sprievodca pre elektrické rozvádzače, snímanie a privolávače.</p>
              <div className="flex items-center gap-2 text-emerald-600 font-bold">
                Spustiť modul RS <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
              </div>
            </div>
            {/* Soft Green Gradient Background Effect */}
            <div className="absolute inset-0 bg-gradient-to-br from-emerald-50/0 to-emerald-50/50 opacity-0 group-hover:opacity-100 transition-opacity -z-10"></div>
          </button>
        </div>

        <footer className="mt-16 pt-8 border-t border-gray-200 flex justify-between items-center text-xs text-gray-400 font-medium">
