    const storedSettings = localStorage.getItem('smartquote_settings');
    if (storedSettings) {
      const parsed = JSON.parse(storedSettings);
      setSettings(parsed);
      const year = new Date().getFullYear().toString().slice(-2);
      setData(prev => ({...prev, number: `RS_SK_${(parsed.nextRsSequence || 1).toString().padStart(3, '0')}_${year}_BA`}));
    }
    const storedProducts = localStorage.getItem('smartquote_products') || '[]';
    setProducts(JSON.parse(storedProducts));
    const storedClients = localStorage.getItem('smartquote_clients') || '[]';
    setClients(JSON.parse(storedClients));
    const storedSuppliers = localStorage.getItem('smartquote_suppliers') || '[]';
    setSuppliers(JSON.parse(storedSuppliers));

    if (data.categories.length === 0) {
        const initCats = RS_CATEGORIES.map(name => ({
            id: `cat-${Math.random()}`, type: 'items' as const, name, items: [], isExpanded: true, section: 'rs' as const
        }));
        setData(prev => ({...prev, categories: initCats}));
    }
  }, []);

  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
    setData(prev => ({ ...prev, layout: { ...prev.layout!, [field]: value } }));
  };

  const calculateTotals = () => {
    let totalSelling = 0;
    data.categories.forEach(cat => {
      if (cat.isHidden) return;
      cat.items.forEach(item => {
        totalSelling += (item.unitPrice * item.quantity) * (1 + data.globalMargin/100);
      });
    });
    const vat = totalSelling * ((data.vatRate || 23) / 100);
    return { totalSelling, vat, gross: totalSelling + vat };
  };

  const totals = calculateTotals();

  const handleSave = () => {
    const quoteToSave = { ...data, lastUpdated: Date.now() };
    const stored = JSON.parse(localStorage.getItem('smartquote_archive') || '[]');
    const filtered = stored.filter((q: any) => q.id !== data.id);
    localStorage.setItem('smartquote_archive', JSON.stringify([...filtered, quoteToSave]));
    alert("RS Ponuka bola uložená do archívu.");
