               <select value={data.layout?.machineType} onChange={e => handleLayoutChange('machineType', e.target.value)} className="w-full h-10 border-2 border-emerald-50 bg-emerald-50/30 rounded-xl px-3 font-bold text-emerald-900 focus:border-emerald-500 outline-none transition"><option value="async">Asynchrónny</option><option value="sync">Synchrónny (Gearless)</option></select></div>
               <div className="grid grid-cols-2 gap-2">
                   <div><label className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Výkon (kW)</label><input type="number" value={data.layout?.machinePower} onChange={e => handleLayoutChange('machinePower', +e.target.value)} className="w-full h-10 border-2 border-emerald-50 rounded-xl px-3 font-bold"/></div>
                   <div><label className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Prúd (A)</label><input type="number" value={data.layout?.machineCurrent} onChange={e => handleLayoutChange('machineCurrent', +e.target.value)} className="w-full h-10 border-2 border-emerald-50 rounded-xl px-3 font-bold"/></div>
               </div>
           </div>

           <div className="col-span-4 space-y-4 border-x border-emerald-100 px-6">
               <h3 className="text-[10px] font-bold text-emerald-600 uppercase tracking-tighter">Brzda a Dvere</h3>
               <div><label className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Napätie brzdy</label><input type="text" value={data.layout?.brakeVoltage} onChange={e => handleLayoutChange('brakeVoltage', e.target.value)} className="w-full h-10 border-2 border-emerald-50 bg-emerald-50/30 rounded-xl px-3 font-bold" placeholder="napr. 110V DC"/></div>
