               <select value={data.layout?.positioningType} onChange={e => handleLayoutChange('positioningType', e.target.value)} className="w-full h-10 border-2 border-emerald-50 rounded-xl px-3 font-bold"><option value="magnetic">Magnetické (Snímače)</option><option value="absolute">Absolútne (LIMAX/USP)</option><option value="encoder">Enkodér na stroji</option></select></div>
               <div className="flex gap-2">
                   <div className="flex-1"><label className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Šachtové sign.</label>
                   <select value={data.layout?.hallSignals} onChange={e => handleLayoutChange('hallSignals', e.target.value)} className="w-full h-10 border-2 border-emerald-50 rounded-xl px-2 font-bold text-xs"><option value="new">Nové</option><option value="original">Pôvodné</option></select></div>
                   <div className="flex-1"><label className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Kabínový pan.</label>
                   <select value={data.layout?.carSignals} onChange={e => handleLayoutChange('carSignals', e.target.value)} className="w-full h-10 border-2 border-emerald-50 rounded-xl px-2 font-bold text-xs"><option value="new">Nový</option><option value="original">Pôvodný</option></select></div>
               </div>
           </div>

           <div className="col-span-12 mt-4">
               <button 
