        onInsert={(wizardItems) => {
            setData(prev => {
                const newCats = prev.categories.map(cat => {
                    const matchedItems = wizardItems.items.filter((i: any) => i.category === cat.name);
                    return {
                        ...cat,
                        items: [...cat.items, ...matchedItems.map((mi: any) => ({
                            id: `mi-${Math.random()}`,
                            description: mi.description,
                            unit: mi.unit,
                            quantity: mi.quantity,
                            unitPrice: mi.price || 0,
                            purchasePrice: mi.price || 0,
                            vatRate: 23
                        }))]
                    };
                });
                return { ...prev, categories: newCats };
            });
            setIsRsWizardOpen(false);
        }}
      />

      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: c})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={() => {}} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: s})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={() => {}} />
      <ProductDatabaseModal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} onSelectProduct={() => {}} products={products} onAddProduct={() => {}} onDeleteProduct={() => {}} />

    </div>
  );
