import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product } from '../types';
import { X, Calculator, Cpu, Zap, Check, AlertTriangle } from 'lucide-react';

interface RsMaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: any) => void;
  products: Product[];
}

export const RsMaterialCalculatorModal: React.FC<RsMaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products
}) => {
  if (!isOpen) return null;

  const calculateRS = () => {
    const items: any[] = [];
    const stops = layout.numberOfStops || 2;

    // Logic for Control System
    const inverterPower = (layout.machinePower || 5.5) > 7.5 ? '11kW' : '7.5kW';
    items.push({
      category: 'Rozvádzač a Riadenie',
      description: `Riadiaci rozvádzač pre ${layout.machineType === 'sync' ? 'Synchrónny' : 'Asynchrónny'} stroj, Invertor ${inverterPower}`,
      quantity: 1,
      unit: 'set',
      price: layout.machineType === 'sync' ? 2200 : 1850
    });

    // Positioning
    if (layout.positioningType === 'absolute') {
      items.push({
          category: 'Snímanie a Polohovanie',
          description: `Absolútne snímanie šachty (LIMAX / USP) - Zdvih ${(layout.travelHeight/1000).toFixed(1)}m`,
          quantity: 1,
          unit: 'set',
          price: 650
      });
    } else {
      items.push({
          category: 'Snímanie a Polohovanie',
          description: `Magnetické snímanie (Poschodové + Koncové magnety)`,
          quantity: 1,
          unit: 'set',
          price: 180
      });
    }

    // Buttons
    if (layout.hallSignals === 'new') {
        items.push({
            category: 'Sachtové Privolávače',
            description: `Tlačidlo privolávača s displejom (Nový nerezový dizajn)`,
            quantity: stops,
            unit: 'ks',
            price: 85
        });
    }

    if (layout.carSignals === 'new') {
        items.push({
            category: 'Kabinové Privolávače',
            description: `Kabinový ovládač - Panel s displejom a núdzovým osvetlením`,
            quantity: 1,
            unit: 'set',
            price: 420
        });
    }

    // Traveling Cable
    items.push({
        category: 'Sachtová Inštalácia',
        description: `Vlečný kábel plochý (Previs) pre modernizáciu`,
        quantity: Math.round(layout.travelHeight / 1000) + 10,
        unit: 'm',
        price: 4.5
    });

    return { items };
  };

  const generated = calculateRS();

  return (
    <div className="fixed inset-0 bg-black/60 z-[120] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
        <div className="p-6 bg-emerald-600 text-white flex justify-between items-center">
            <div className="flex items-center gap-3">
                <div className="bg-white/20 p-2 rounded-xl">
                    <Cpu size={24}/>
                </div>
                <div>
                    <h2 className="text-xl font-black uppercase">RS Sprievodca</h2>
                    <p className="text-xs text-emerald-100">Návrh komponentov modernizácie riadenia</p>
                </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-black/10 rounded-full transition"><X size={24}/></button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
            <div className="bg-emerald-50 border-2 border-emerald-100 p-4 rounded-2xl flex gap-4 items-start">
                <AlertTriangle className="text-emerald-600 shrink-0" size={24}/>
                <p className="text-sm text-emerald-800 font-medium">
                    Tento sprievodca navrhol položky na základe stroja <strong>{layout.machinePower}kW</strong> a <strong>{layout.numberOfStops} staníc</strong>. Skontrolujte zoznam pred vložením do ponuky.
                </p>
            </div>

            <div className="space-y-3">
                {generated.items.map((item, i) => (
                    <div key={i} className="flex justify-between items-center p-4 bg-gray-50 rounded-xl border border-gray-100 hover:border-emerald-300 transition group">
                        <div>
