                <button onClick={() => setIsEmailModalOpen(true)} className="px-3 py-2 h-9 bg-green-600 hover:bg-green-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm whitespace-nowrap"><Mail size={16}/> Odoslať</button>
                <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-2 h-9 bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold rounded flex items-center gap-2 border border-purple-300 text-sm whitespace-nowrap"><Settings size={16}/> Katalóg</button>
                <button onClick={handleSaveCurrentQuote} className="px-3 py-2 h-9 bg-green-100 hover:bg-green-200 text-green-800 font-bold rounded flex items-center gap-2 border border-green-300 text-sm whitespace-nowrap"><Save size={16}/> Uložiť</button>
                <button onClick={() => setShowArchive(true)} className="px-3 py-2 h-9 bg-gray-200 hover:bg-gray-300 rounded text-gray-700 font-bold flex items-center gap-2 text-sm whitespace-nowrap"><Archive size={16}/> Archív</button>
                <button onClick={onLogout} className="ml-2 p-2 h-9 bg-red-100 hover:bg-red-200 text-red-700 rounded-full"><LogOut size={16}/></button>
            </div>
        </div>
      </div>

      {/* PÔVODNÝ CONFIG PANEL */}
      <div className="max-w-[210mm] mx-auto mb-8 p-6 bg-amber-50 rounded-xl border border-amber-200 shadow-sm text-sm no-print">
             <div className="grid grid-cols-12 gap-4 mb-4 pb-4 border-b border-amber-200">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1"><Sliders size={16}/> Základné Parametre</div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Typ výťahu</label><select value={data.layout?.liftType} onChange={e => handleLayoutChange('liftType', e.target.value as any)} className="w-full h-10 border border-gray-300 rounded px-2 bg-white font-bold"><option value="passenger">Osobný</option><option value="freight">Nákladný</option></select></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => handleLayoutChange('ratedLoad', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Stanice</label><input type="number" value={data.layout?.numberOfStops} onChange={e => handleLayoutChange('numberOfStops', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-6"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Názov projektu / Referencia</label><input type="text" value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="w-full h-10 border border-gray-300 rounded px-3 font-bold bg-white text-blue-800 uppercase" placeholder="Projekt..."/></div>
             </div>
             <div className="flex justify-center">
                <button onClick={() => setIsMaterialModalOpen(true)} className="px-12 py-3 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black rounded-xl shadow-lg flex items-center gap-2 transform hover:scale-105 transition-all uppercase tracking-widest"><Calculator size={20}/> Materiálový Sprievodca</button>
             </div>
      </div>

      {/* PÔVODNÝ PRINT LAYOUT */}
      <div ref={printContentRef} className="max-w-[210mm] mx-auto bg-white shadow-2xl border border-gray-200 min-h-[297mm] p-[15mm] md:p-[20mm] print:shadow-none print:p-0 print:w-full text-gray-900 print:text-black">
        <div className="print-container">
            <div className="mb-8 print:mb-4 print-header">
                <div className="flex justify-between items-start mb-6 print:mb-2">
