            </div>

            <div className="mb-8">
                <TechSpecTable data={data.layout || DEFAULT_LAYOUT} isVisible={true} onToggleVisibility={() => {}} embedded={true} />
            </div>

            <div className="space-y-4">
                {data.categories.map(cat => (
                    <CategoryTable 
                        key={cat.id} category={cat} currency={data.currency} globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === id ? {...c, [f]: v} : c)}))}
                        onDeleteCategory={(id) => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id !== id)}))}
