  entrances: 'A', counterWeightPosition: 'back', machineRoomPosition: 'above',
  machineType: 'async', machinePower: 4.5, machineCurrent: 12.0, brakeVoltage: '110V DC', 
  doorControl: 'original', hallSignals: 'new', carSignals: 'new', positioningType: 'magnetic',
