};

export const RsModule: React.FC<{ onBack: () => void, onLogout: () => void }> = ({ onBack, onLogout }) => {
  const [data, setData] = useState<QuoteData>({
    id: `rs-${Date.now()}`, number: 'RS_SK_001_24_BA', type: 'quote', title: 'Cenová Ponuka - Modernizácia Riadenia (RS)', moduleType: 'rs',
    date: new Date().toISOString().split('T')[0], validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
    supplier: { name: 'Moja Firma s.r.o.', details: 'IČO: 12345678, DPH: SK12345678' },
    client: { name: '', details: '' }, layout: { ...DEFAULT_RS_LAYOUT },
    categories: [], terms: '', currency: '€', globalMargin: 20, shaftMargin: 20, vatRate: 23, hideItemPrices: true, showTechSpecs: true
  });

  const [settings, setSettings] = useState<AppSettings>({ nextCpSequence: 1, nextObjSequence: 1, nextPlSequence: 1, nextRsSequence: 1 });
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [isRsWizardOpen, setIsRsWizardOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);

  useEffect(() => {
    const storedSettings = localStorage.getItem('smartquote_settings');
    if (storedSettings) {
      const parsed = JSON.parse(storedSettings);
      setSettings(parsed);
      const year = new Date().getFullYear().toString().slice(-2);
      setData(prev => ({...prev, number: `RS_SK_${(parsed.nextRsSequence || 1).toString().padStart(3, '0')}_${year}_BA`}));
    }
    const storedProducts = localStorage.getItem('smartquote_products') || '[]';
    setProducts(JSON.parse(storedProducts));
    const storedClients = localStorage.getItem('smartquote_clients') || '[]';
    setClients(JSON.parse(storedClients));
    const storedSuppliers = localStorage.getItem('smartquote_suppliers') || '[]';
    setSuppliers(JSON.parse(storedSuppliers));

    if (data.categories.length === 0) {
        const initCats = RS_CATEGORIES.map(name => ({
            id: `cat-${Math.random()}`, type: 'items' as const, name, items: [], isExpanded: true, section: 'rs' as const
        }));
        setData(prev => ({...prev, categories: initCats}));
    }
  }, []);

  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
    setData(prev => ({ ...prev, layout: { ...prev.layout!, [field]: value } }));
  };

  const calculateTotals = () => {
    let totalSelling = 0;
    data.categories.forEach(cat => {
      cat.items.forEach(item => {
        totalSelling += (item.unitPrice * item.quantity) * (1 + data.globalMargin/100);
      });
    });
    const vat = totalSelling * ((data.vatRate || 23) / 100);
    return { totalSelling, vat, gross: totalSelling + vat };
  };

  const totals = calculateTotals();

  const handleSave = () => {
    const quoteToSave = { ...data, lastUpdated: Date.now() };
    const stored = JSON.parse(localStorage.getItem('smartquote_archive') || '[]');
    localStorage.setItem('smartquote_archive', JSON.stringify([...stored.filter((q:any)=>q.id!==data.id), quoteToSave]));
    alert("RS Ponuka bola uložená.");
  };

  return (
    <div className="min-h-screen bg-emerald-50/20 p-4 md:p-8 font-sans print:bg-white print:p-0">
      {/* RS TOOLBAR */}
      <div className="no-print mb-6 max-w-[210mm] mx-auto">
        <div className="flex justify-between items-center mb-6">
