          <div className="flex gap-2">
            <button onClick={() => window.print()} className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg flex items-center gap-2 shadow"><Printer size={18}/> Tlačiť RS</button>
            <button onClick={handleSave} className="px-4 py-2 bg-white border border-emerald-200 text-emerald-700 font-bold rounded-lg flex items-center gap-2 hover:bg-emerald-50 transition shadow-sm"><Save size={18}/> Uložiť</button>
            <button onClick={onLogout} className="p-2 bg-red-100 text-red-700 rounded-full"><LogOut size={18}/></button>
          </div>
        </div>

        <div className="flex items-center gap-4 mb-8 bg-white p-4 rounded-2xl border border-emerald-100 shadow-sm">
            <div className="p-4 bg-emerald-600 text-white rounded-2xl shadow-xl shadow-emerald-100">
                <Cpu size={32}/>
            </div>
            <div>
                <h1 className="text-2xl font-black text-slate-900 leading-tight">Modul Modernizácie RS</h1>
                <p className="text-emerald-600 font-black text-xs uppercase tracking-[0.2em]">{data.number}</p>
            </div>
        </div>
      </div>

      {/* RS CONFIG PANEL */}
      <div className="max-w-[210mm] mx-auto mb-8 p-8 bg-white rounded-2xl border-2 border-emerald-100 shadow-xl shadow-emerald-100/50 text-sm no-print">
        <div className="grid grid-cols-12 gap-6">
           <div className="col-span-12 font-black text-emerald-800 uppercase flex items-center gap-2 border-b border-emerald-50 pb-4 mb-2">
               <Zap size={20} className="text-emerald-500"/> Technická Špecifikácia Riadenia
           </div>

