import React from 'react';
import { LiftLayoutData, Product } from '../types';
import { X, Calculator, Cpu, Check, AlertTriangle } from 'lucide-react';

interface RsMaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: any) => void;
  products: Product[];
}

export const RsMaterialCalculatorModal: React.FC<RsMaterialCalculatorModalProps> = ({
  isOpen, onClose, layout, onInsert, products
}) => {
  if (!isOpen) return null;

  const calculateRS = () => {
    const items: any[] = [];
    const stops = layout.numberOfStops || 2;

    // 1. Rozvádzač
    const inverterPower = (layout.machinePower || 4.5) > 7.5 ? '11kW' : '7.5kW';
    items.push({
      category: 'Rozvádzač a Riadenie',
      description: `Riadiaci rozvádzač pre ${layout.machineType === 'sync' ? 'Gearless' : 'Asynchrónny'} stroj, Invertor ${inverterPower}`,
      quantity: 1, unit: 'set', price: layout.machineType === 'sync' ? 2450 : 1980
    });

    // 2. Snímanie
    if (layout.positioningType === 'absolute') {
      items.push({
          category: 'Snímanie a Polohovanie',
          description: `Absolútne snímanie šachty (Enkodérový pás) - Zdvih ${(layout.travelHeight/1000).toFixed(1)}m`,
          quantity: 1, unit: 'set', price: 680
      });
    } else {
      items.push({
          category: 'Snímanie a Polohovanie',
          description: `Magnetické snímanie (Poschodové a koncové magnety)`,
          quantity: 1, unit: 'set', price: 210
      });
    }

    // 3. Privolávače
    if (layout.hallSignals === 'new') {
        items.push({
            category: 'Sachtové Privolávače',
            description: `Sachtový privolávač - Nerezový panel s LCD displejom`,
            quantity: stops, unit: 'ks', price: 95
        });
    }

    // 4. Inštalácia
    items.push({
        category: 'Sachtová Inštalácia',
        description: `Plochý vlečný kábel pre RS (Previs)`,
        quantity: Math.round(layout.travelHeight / 1000) + 12,
        unit: 'm', price: 5.2
    });

    return { items };
  };

  const generated = calculateRS();

  return (
    <div className="fixed inset-0 bg-slate-900/80 z-[150] flex items-center justify-center p-4 backdrop-blur-sm">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-300">
        <div className="p-6 bg-emerald-600 text-white flex justify-between items-center">
            <div className="flex items-center gap-4">
                <div className="bg-white/20 p-3 rounded-2xl"><Cpu size={28}/></div>
                <div>
                    <h2 className="text-2xl font-black uppercase tracking-tight">RS Kalkulátor</h2>
                    <p className="text-xs text-emerald-100 font-bold opacity-80 uppercase tracking-widest">Modernizácia Riadenia</p>
                </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-black/10 rounded-full transition"><X size={24}/></button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/50">
            <div className="bg-emerald-50 border-2 border-emerald-100 p-5 rounded-2xl flex gap-4 items-start shadow-sm">
                <AlertTriangle className="text-emerald-600 shrink-0" size={24}/>
                <p className="text-sm text-emerald-800 font-bold leading-relaxed">
                    Navrhli sme komponenty pre stroj <span className="underline">{layout.machinePower}kW</span> a <span className="underline">{layout.numberOfStops} staníc</span>. Ceny sú odhadované podľa aktuálneho trhu.
                </p>
            </div>

            <div className="space-y-3">
                {generated.items.map((item, i) => (
                    <div key={i} className="flex justify-between items-center p-5 bg-white rounded-2xl border border-slate-100 shadow-sm hover:border-emerald-400 transition group">
                        <div>
                            <div className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.2em] mb-1">{item.category}</div>
                            <div className="font-bold text-slate-800">{item.description}</div>
                        </div>
                        <div className="text-right">
                            <div className="font-black text-slate-900 text-lg">{item.quantity} {item.unit}</div>
                            <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Odhad: {item.price} €/mj</div>
                        </div>
                    </div>
                ))}
            </div>
        </div>

        <div className="p-6 bg-white border-t border-slate-100 flex justify-end gap-3">
            <button onClick={onClose} className="px-6 py-3 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 transition">Zrušiť</button>
            <button 
                onClick={() => onInsert(generated)}
                className="px-10 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl shadow-emerald-100 flex items-center gap-3 hover:bg-emerald-700 transition uppercase tracking-widest text-sm"
            >
                <Check size={20}/> Vložiť do rozpočtu
            </button>
        </div>
      </div>
    </div>
  );
};

