              if (data.number === 'CP_SK_001_24_BA') {
                  const year = new Date().getFullYear().toString().slice(-2);
                  const numStr = (parsed.nextCpSequence || 1).toString().padStart(3, '0');
                  setData(prev => ({...prev, number: `CP_SK_${numStr}_${year}_BA`}));
              }
          } catch (e) {}
      }
      if (data.categories.length === 0) {
          setData(prev => ({...prev, categories: DEFAULT_CATEGORIES_LIST.map(name => ({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' }))}));
      }
      const storedProducts = localStorage.getItem('smartquote_products');
      if (storedProducts) setProducts(JSON.parse(storedProducts));
      const storedClients = localStorage.getItem('smartquote_clients');
      if (storedClients) setClients(JSON.parse(storedClients));
      const storedSuppliers = localStorage.getItem('smartquote_suppliers');
      if (storedSuppliers) setSuppliers(JSON.parse(storedSuppliers));
  }, []);

  const calculateTotals = () => {
      let totalSelling = 0;
      data.categories.forEach(cat => {
          if (cat.isHidden) return;
          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;
          cat.items.forEach(item => {
              totalSelling += (item.quantity * item.unitPrice) * (1 + margin / 100);
          });
      });
      const vatRate = data.vatRate ?? 23; 
      return { totalSelling, vat: totalSelling * (vatRate / 100), gross: totalSelling * (1 + vatRate / 100) };
  };
  const totals = calculateTotals();

  const handleLogin = () => { sessionStorage.setItem('auth', 'true'); setIsAuthenticated(true); };
  const handleLogout = () => { sessionStorage.removeItem('auth'); setIsAuthenticated(false); }

  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
      setData(prev => ({ ...prev, layout: { ...prev.layout!, [field]: value } }));
  };

  // Fix: Added missing handleAddItem function to resolve reference error
  const handleAddItem = (catId: string, isSurcharge = false) => {
    setData(prev => ({
      ...prev,
      categories: prev.categories.map(c =>
        c.id === catId
          ? {
              ...c,
              items: [
                ...c.items,
                {
                  id: generateId(),
                  description: isSurcharge ? 'Príplatok / Príslušenstvo' : 'Nová položka',
                  unit: 'ks',
                  quantity: 1,
                  unitPrice: 0,
                  purchasePrice: 0,
                  vatRate: 23,
                  isSurcharge,
                },
              ],
            }
          : c
      ),
    }));
  };

  const handleSaveCurrentQuote = () => {
      const exists = savedQuotes.find(q => q.id === data.id);
      const newArchive = exists ? savedQuotes.map(q => q.id === data.id ? {...data, lastUpdated: Date.now()} : q) : [...savedQuotes, {...data, lastUpdated: Date.now()}];
      setSavedQuotes(newArchive);
      alert(`Doklad ${data.number} uložený.`);
  };

  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev, wizardData: wData };
          const activeCategoryNames = new Set(wData.categoryOrder);
          if (wData.includeAssembly) activeCategoryNames.add('Montáž');
          if (wData.includeTransport) activeCategoryNames.add('Doprava');
          if (wData.includePackaging) activeCategoryNames.add('Balné');

          newData.categories = newData.categories.filter(c => activeCategoryNames.has(c.name));
          activeCategoryNames.forEach(catName => {
               let cat = newData.categories.find(c => c.name === catName);
               if (!cat) {
                   cat = { id: generateId(), name: catName, type: 'items', items: [], isExpanded: true, section: catName === 'Oceľová konštrukcia' ? 'shaft' : 'lift' };
                   newData.categories.push(cat);
               }
               cat.items = [];
          });

          wData.items.forEach(bomItem => {
              const category = newData.categories.find(c => c.name === bomItem.category);
              if (category) {
                  category.items.push({ id: generateId(), description: bomItem.description, unit: bomItem.unit, quantity: bomItem.quantity, unitPrice: bomItem.price || 0, purchasePrice: 0, vatRate: 23 });
              }
          });

          if (wData.includeAssembly) { const cat = newData.categories.find(c => c.name === 'Montáž'); if (cat) cat.items.push({ id: generateId(), description: 'Montáž technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includeTransport) { const cat = newData.categories.find(c => c.name === 'Doprava'); if (cat) cat.items.push({ id: generateId(), description: 'Doprava materiálu', unit: 'kpl', quantity: 1, unitPrice: wData.transportPrice || 200, purchasePrice: 0, vatRate: 23 }); }
          if (wData.includePackaging) { const cat = newData.categories.find(c => c.name === 'Balné'); if (cat) cat.items.push({ id: generateId(), description: 'Balné', unit: 'kpl', quantity: 1, unitPrice: wData.packagingPrice || 50, purchasePrice: 0, vatRate: 23 }); }

          return newData;
      });
  };

  if (!isAuthenticated) return <LoginGate onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-8 font-sans print:bg-white print:p-0">
      <div className="no-print mb-6">
        <div className="flex flex-col xl:flex-row justify-between items-center mb-4 gap-4">
            <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2 self-start xl:self-center">
                <Calculator className="text-blue-600"/> SmartQuote SK <span className="text-xs bg-gray-200 text-gray-600 px-2 py-1 rounded">v{APP_VERSION}</span>
            </h1>
            <div className="flex flex-wrap gap-2 items-center justify-end w-full xl:w-auto">
                <button onClick={() => window.print()} className="px-3 py-2 h-9 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm whitespace-nowrap"><Printer size={16}/> Tlačiť / PDF</button>
                <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-2 h-9 bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold rounded flex items-center gap-2 border border-purple-300 text-sm whitespace-nowrap"><Settings size={16}/> Katalóg</button>
                <button onClick={handleSaveCurrentQuote} className="px-3 py-2 h-9 bg-green-100 hover:bg-green-200 text-green-800 font-bold rounded flex items-center gap-2 border border-green-300 text-sm whitespace-nowrap"><Save size={16}/> Uložiť</button>
                <button onClick={() => setShowArchive(true)} className="px-3 py-2 h-9 bg-gray-200 hover:bg-gray-300 rounded text-gray-700 font-bold flex items-center gap-2 text-sm whitespace-nowrap"><Archive size={16}/> Archív</button>
                <button onClick={handleLogout} className="ml-2 p-2 h-9 bg-red-100 hover:bg-red-200 text-red-700 rounded-full"><LogOut size={16}/></button>
            </div>
        </div>
      </div>

      <div className="max-w-[210mm] mx-auto mb-8 p-6 bg-amber-50 rounded-xl border border-amber-200 shadow-sm text-sm no-print">
             <div className="grid grid-cols-12 gap-4 mb-4 pb-4 border-b border-amber-200">
                <div className="col-span-12 font-bold text-amber-900 uppercase flex items-center gap-2 mb-1"><Sliders size={16}/> Základné Parametre</div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Typ výťahu</label><select value={data.layout?.liftType} onChange={e => handleLayoutChange('liftType', e.target.value as any)} className="w-full h-10 border border-gray-300 rounded px-2 bg-white font-bold"><option value="passenger">Osobný</option><option value="freight">Nákladný</option></select></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Nosnosť (kg)</label><input type="number" value={data.layout?.ratedLoad} onChange={e => handleLayoutChange('ratedLoad', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-2"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Stanice</label><input type="number" value={data.layout?.numberOfStops} onChange={e => handleLayoutChange('numberOfStops', +e.target.value)} className="w-full h-10 border border-gray-300 rounded px-2 text-center font-bold text-lg bg-white"/></div>
                <div className="col-span-6"><label className="text-[10px] uppercase font-bold text-gray-500 block mb-1">Názov projektu / Referencia</label><input type="text" value={data.clientReference} onChange={e => setData({...data, clientReference: e.target.value})} className="w-full h-10 border border-gray-300 rounded px-3 font-bold bg-white text-blue-800 uppercase" placeholder="Projekt..."/></div>
             </div>
             <div className="flex justify-center">
                <button onClick={() => setIsMaterialModalOpen(true)} className="px-12 py-3 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black rounded-xl shadow-lg flex items-center gap-2 transform hover:scale-105 transition-all uppercase tracking-widest"><Calculator size={20}/> Materiálový Sprievodca</button>
             </div>
      </div>

      <div ref={printContentRef} className="max-w-[210mm] mx-auto bg-white shadow-2xl border border-gray-200 min-h-[297mm] p-[15mm] md:p-[20mm] print:shadow-none print:p-0 print:w-full text-gray-900 print:text-black">
        <div className="print-container">
            <div className="flex justify-between items-start mb-8">
                <div className="w-2/3">
                    <h1 className="text-4xl font-bold uppercase">{data.title}</h1>
                    <div className="text-lg text-gray-500">{data.number}</div>
                </div>
                <div className="text-right text-sm">
                   <div>Dátum: {data.date}</div>
                   <div>Platnosť: {data.validUntil}</div>
                </div>
            </div>
            <div className="grid grid-cols-2 gap-8 items-start border-t border-b border-gray-100 py-6 mb-8">
                <div>
                    <h3 className="text-[10px] font-bold text-gray-400 uppercase mb-2">Dodávateľ</h3>
                    <div className="font-bold text-sm uppercase">{data.supplier.name}</div>
                    <div className="text-xs text-gray-600 whitespace-pre-wrap">{data.supplier.details}</div>
                </div>
                <div>
                    <h3 className="text-[10px] font-bold text-gray-400 uppercase mb-2">Klient</h3>
                    <div className="font-bold text-sm uppercase">{data.client.name || '---'}</div>
                    <div className="text-xs text-gray-600 whitespace-pre-wrap">{data.client.details}</div>
                </div>
            </div>

            {data.showTechSpecs && <TechSpecTable data={data.layout || DEFAULT_LAYOUT} isVisible={true} onToggleVisibility={() => {}} embedded />}

            <div className="space-y-4 mt-8">
                {data.categories.map(cat => (
                    <CategoryTable key={cat.id} category={cat} currency={data.currency} globalMargin={cat.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id === id ? {...c, [f]: v} : c)}))}
                        onDeleteCategory={() => {}} onAddItem={(cid, sur) => handleAddItem(cid, sur)} onUpdateItem={(cid, iid, f, v) => {
                            setData(prev => ({...prev, categories: prev.categories.map(c => c.id === cid ? {...c, items: c.items.map(i => i.id === iid ? {...i, [f]: v} : i)} : c)}));
                        }} onDeleteItem={(cid, iid) => {
                            setData(prev => ({...prev, categories: prev.categories.map(c => c.id === cid ? {...c, items: c.items.filter(i => i.id !== iid)} : c)}));
                        }} onAiSuggest={() => {}} onOpenCatalog={() => setIsProductModalOpen(true)} isAiLoading={false} hidePrices={data.hideItemPrices} readOnly />
                ))}
            </div>

            <div className="mt-12 pt-4 border-t-2 border-gray-800 flex justify-end">
                <div className="w-64">
                    <div className="flex justify-between text-2xl font-bold"><span>Cena Spolu:</span><span>{totals.totalSelling.toLocaleString('sk-SK')} {data.currency}</span></div>
                    <div className="text-right text-xs text-gray-400">bez DPH</div>
                </div>
            </div>
        </div>
      </div>

      <MaterialCalculatorModal isOpen={isMaterialModalOpen} onClose={() => setIsMaterialModalOpen(false)} layout={data.layout || DEFAULT_LAYOUT} onInsert={handleMaterialWizardInsert} products={products} customCategories={availableCategories} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} />
    </div>
  );
};
